import type { ActionFunctionArgs, LoaderFunctionArgs } from "@remix-run/node";
import { json } from "@remix-run/node";
import {
  Form,
  useActionData,
  useLoaderData,
  useNavigation,
} from "@remix-run/react";
import {
  Page,
  Layout,
  Card,
  FormLayout,
  TextField,
  Select,
  Checkbox,
  Button,
  Text,
  BlockStack,
  InlineStack,
  Divider,
  Icon,
  ChoiceList,
} from "@shopify/polaris";
import { TitleBar, useAppBridge } from "@shopify/app-bridge-react";
import { useState, useEffect } from "react";
import { authenticate } from "../shopify.server";
import { SettingsIcon, LocationIcon } from "@shopify/polaris-icons";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);

  // In a real app, you would load settings from your database
  const settings = {
    storeName: "Reservify Store",
    businessAddress: "123 Main St, City, State",
    defaultTimeSlot: "60",
    defaultCapacity: "10",
    requireDeposit: true,
    depositAmount: "25",
    autoConfirm: false,
    notificationFrequency: "immediately",
    emailNotifications: ["new-reservation", "cancellation"],
    defaultSorting: "newest",
    displayOptions: ["show-duration", "show-capacity"],
    cancellationPolicy: "24-hours",
    bufferTime: "15",
  };

  return json({ settings });
};

export const action = async ({ request }: ActionFunctionArgs) => {
  await authenticate.admin(request);

  const formData = await request.formData();
  const settings = Object.fromEntries(formData);

  // In a real app, you would save settings to your database
  console.log("Saving settings:", settings);

  return json({ success: true, message: "Settings saved successfully!" });
};

export default function Settings() {
  const { settings } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const shopify = useAppBridge();

  const [formData, setFormData] = useState(settings);
  const [hasChanges, setHasChanges] = useState(false);

  const isLoading = navigation.state === "submitting";

  useEffect(() => {
    const hasFormChanges =
      JSON.stringify(formData) !== JSON.stringify(settings);
    setHasChanges(hasFormChanges);
  }, [formData, settings]);

  useEffect(() => {
    if (actionData?.success) {
      shopify.toast.show(actionData.message);
      setHasChanges(false);
    }
  }, [actionData, shopify]);

  const handleInputChange = (field: string, value: any) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
  };

  const timeSlotOptions = [
    { label: "30 minutes", value: "30" },
    { label: "60 minutes", value: "60" },
    { label: "90 minutes", value: "90" },
    { label: "120 minutes", value: "120" },
  ];

  const notificationOptions = [
    { label: "Immediately", value: "immediately" },
    { label: "Hourly digest", value: "hourly" },
    { label: "Daily digest", value: "daily" },
  ];

  const sortingOptions = [
    { label: "Newest first", value: "newest" },
    { label: "Oldest first", value: "oldest" },
    { label: "By time slot", value: "time" },
    { label: "By capacity", value: "capacity" },
  ];

  const emailNotificationChoices = [
    { label: "New reservation notifications", value: "new-reservation" },
    { label: "Cancellation alerts", value: "cancellation" },
    { label: "Reminder notifications", value: "reminder" },
    { label: "Capacity warnings", value: "capacity-warning" },
  ];

  const displayChoices = [
    { label: "Show duration", value: "show-duration" },
    { label: "Show capacity", value: "show-capacity" },
    { label: "Show availability", value: "show-availability" },
  ];

  const cancellationOptions = [
    { label: "24 hours before", value: "24-hours" },
    { label: "48 hours before", value: "48-hours" },
    { label: "1 week before", value: "1-week" },
    { label: "No cancellation allowed", value: "none" },
  ];

  const bufferOptions = [
    { label: "No buffer", value: "0" },
    { label: "15 minutes", value: "15" },
    { label: "30 minutes", value: "30" },
    { label: "60 minutes", value: "60" },
  ];

  return (
    <Page>
      <TitleBar title="Settings" />
      <Form method="post">
        <Layout>
          <Layout.Section>
            <BlockStack gap="800">
              {/* Store Settings */}
              <Layout>
                <Layout.Section variant="oneThird">
                  <BlockStack gap="200">
                    <Text as="h2" variant="headingMd">
                      Store Settings
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Manage your store information
                    </Text>
                  </BlockStack>
                </Layout.Section>
                <Layout.Section>
                  <Card>
                    <BlockStack gap="400">
                      <InlineStack align="space-between" blockAlign="center">
                        <InlineStack gap="200" blockAlign="center">
                          <Icon source={SettingsIcon} />
                          <Text as="p" variant="bodyMd">
                            {formData.storeName}
                          </Text>
                        </InlineStack>
                        <Button variant="tertiary" size="micro">
                          Edit
                        </Button>
                      </InlineStack>
                      <Divider />
                      <InlineStack align="space-between" blockAlign="center">
                        <InlineStack gap="200" blockAlign="center">
                          <Icon source={LocationIcon} />
                          <BlockStack gap="050">
                            <Text as="p" variant="bodyMd">
                              Business address
                            </Text>
                            <Text as="p" variant="bodySm" tone="subdued">
                              {formData.businessAddress}
                            </Text>
                          </BlockStack>
                        </InlineStack>
                        <Button variant="tertiary" size="micro">
                          Edit
                        </Button>
                      </InlineStack>
                    </BlockStack>
                  </Card>
                </Layout.Section>
              </Layout>

              {/* Reservation Defaults */}
              <Layout>
                <Layout.Section variant="oneThird">
                  <BlockStack gap="200">
                    <Text as="h2" variant="headingMd">
                      Reservation Defaults
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Set default options for new reservations
                    </Text>
                  </BlockStack>
                </Layout.Section>
                <Layout.Section>
                  <Card>
                    <FormLayout>
                      <Select
                        label="Default time slot duration"
                        options={timeSlotOptions}
                        value={formData.defaultTimeSlot}
                        onChange={(value) =>
                          handleInputChange("defaultTimeSlot", value)
                        }
                        name="defaultTimeSlot"
                      />
                      <TextField
                        label="Default capacity"
                        type="number"
                        value={formData.defaultCapacity}
                        onChange={(value) =>
                          handleInputChange("defaultCapacity", value)
                        }
                        name="defaultCapacity"
                        helpText="Maximum number of people per reservation"
                        autoComplete="off"
                      />
                      <Checkbox
                        label="Require deposit"
                        checked={formData.requireDeposit}
                        onChange={(checked) =>
                          handleInputChange("requireDeposit", checked)
                        }
                        name="requireDeposit"
                      />
                      {formData.requireDeposit && (
                        <TextField
                          label="Deposit amount"
                          type="number"
                          value={formData.depositAmount}
                          onChange={(value) =>
                            handleInputChange("depositAmount", value)
                          }
                          name="depositAmount"
                          prefix="$"
                          helpText="Amount to charge as deposit"
                          autoComplete="off"
                        />
                      )}
                      <Checkbox
                        label="Auto-confirm reservations"
                        checked={formData.autoConfirm}
                        onChange={(checked) =>
                          handleInputChange("autoConfirm", checked)
                        }
                        name="autoConfirm"
                        helpText="Automatically confirm reservations without manual approval"
                      />
                    </FormLayout>
                  </Card>
                </Layout.Section>
              </Layout>

              {/* Booking Experience */}
              <Layout>
                <Layout.Section variant="oneThird">
                  <BlockStack gap="200">
                    <Text as="h2" variant="headingMd">
                      Booking Experience
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Configure how customers make reservations
                    </Text>
                  </BlockStack>
                </Layout.Section>
                <Layout.Section>
                  <Card>
                    <FormLayout>
                      <Select
                        label="Cancellation policy"
                        options={cancellationOptions}
                        value={formData.cancellationPolicy}
                        onChange={(value) =>
                          handleInputChange("cancellationPolicy", value)
                        }
                        name="cancellationPolicy"
                      />
                      <Select
                        label="Buffer time between reservations"
                        options={bufferOptions}
                        value={formData.bufferTime}
                        onChange={(value) =>
                          handleInputChange("bufferTime", value)
                        }
                        name="bufferTime"
                        helpText="Time gap between consecutive reservations"
                      />
                    </FormLayout>
                  </Card>
                </Layout.Section>
              </Layout>

              {/* Calendar Settings */}
              <Layout>
                <Layout.Section variant="oneThird">
                  <BlockStack gap="200">
                    <Text as="h2" variant="headingMd">
                      Calendar Settings
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Configure your reservation calendar
                    </Text>
                  </BlockStack>
                </Layout.Section>
                <Layout.Section>
                  <Card>
                    <FormLayout>
                      <Select
                        label="Default sorting"
                        options={sortingOptions}
                        value={formData.defaultSorting}
                        onChange={(value) =>
                          handleInputChange("defaultSorting", value)
                        }
                        name="defaultSorting"
                      />
                      <ChoiceList
                        title="Display options"
                        choices={displayChoices}
                        selected={formData.displayOptions}
                        onChange={(selected) =>
                          handleInputChange("displayOptions", selected)
                        }
                        allowMultiple
                        name="displayOptions"
                      />
                    </FormLayout>
                  </Card>
                </Layout.Section>
              </Layout>

              {/* Notifications */}
              <Layout>
                <Layout.Section variant="oneThird">
                  <BlockStack gap="200">
                    <Text as="h2" variant="headingMd">
                      Notifications
                    </Text>
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Manage your business notifications
                    </Text>
                  </BlockStack>
                </Layout.Section>
                <Layout.Section>
                  <Card>
                    <FormLayout>
                      <Select
                        label="Notification frequency"
                        options={notificationOptions}
                        value={formData.notificationFrequency}
                        onChange={(value) =>
                          handleInputChange("notificationFrequency", value)
                        }
                        name="notificationFrequency"
                      />
                      <ChoiceList
                        title="Email notifications"
                        choices={emailNotificationChoices}
                        selected={formData.emailNotifications}
                        onChange={(selected) =>
                          handleInputChange("emailNotifications", selected)
                        }
                        allowMultiple
                        name="emailNotifications"
                      />
                    </FormLayout>
                  </Card>
                </Layout.Section>
              </Layout>

              {/* Save Button */}
              <InlineStack align="end">
                <Button
                  variant="primary"
                  submit
                  loading={isLoading}
                  disabled={!hasChanges}
                >
                  Save settings
                </Button>
              </InlineStack>
            </BlockStack>
          </Layout.Section>
        </Layout>
      </Form>
    </Page>
  );
}
